"""Practical RU/FR articles; every legal claim has a narrow official-source basis."""

ARTICLES_HTML = {
 'how-to-choose-residence': {
  'ru': '''<p class="sr-meta">Обновлено 21.11.2026 · Информация общего характера</p><p>Виза, разрешение на временное проживание (РВП) и вид на жительство (ВНЖ) отвечают на разные вопросы. Выбор начинается с того, <strong>почему, на какой срок и с кем</strong> вы планируете жить в России, а также с проверки гражданства и уже имеющихся документов. Не выбирайте процедуру только по названию разрешения.</p><h2>Сравните маршруты до сбора документов</h2><table><caption>Общая карта вопросов; конкретные основания и сроки проверяются по действующему закону</caption><thead><tr><th scope="col">Маршрут</th><th scope="col">Что выяснить</th><th scope="col">Типичная ошибка</th></tr></thead><tbody><tr><td>Въезд и виза</td><td>Цель поездки, гражданство, место подачи, срок пребывания</td><td>Считать любую визу основанием для долгого проживания</td></tr><tr><td>РВП</td><td>Основание, квота или исключение, регион, документы</td><td>Собирать пакет без проверки основания</td></tr><tr><td>ВНЖ</td><td>Доступный путь, предыдущий статус, ограничения и подтверждения</td><td>Переносить чужой сценарий на свой случай</td></tr></tbody></table><h2>Порядок самостоятельной подготовки</h2><ol><li>Запишите гражданство, государства проживания и историю въездов в Россию.</li><li>Укажите цель и предполагаемую длительность пребывания, состав семьи, место работы или учёбы.</li><li>Составьте список имеющихся паспортов, виз, миграционных документов и решений органов.</li><li>Сравните возможные основания по <a href="http://pravo.gov.ru/proxy/ips/?docbody=&nd=102078147">закону № 115-ФЗ</a>. Для программы «Разделение ценностей» отдельно прочитайте <a href="https://publication.pravo.gov.ru/document/0001202408190001">Указ № 702</a> и <a href="/ru/migration/decree-702/">наш разбор</a>.</li><li>Только после выбора правового маршрута уточняйте комплект, перевод документов, орган подачи и сроки.</li></ol><h2>Пример</h2><p>Семья планирует переезд, но у супругов разное гражданство, а один уже находится в России. У них может не быть одного общего набора документов и одинакового порядка подачи. Сначала составьте отдельную карточку статуса на каждого человека, затем соедините их в план семьи.</p><h2>Частые вопросы</h2><details><summary>Можно ли сразу подавать на ВНЖ?</summary><p>В отдельных ситуациях закон предусматривает специальные основания. Ответ зависит от фактов и действующей редакции закона № 115-ФЗ; одного гражданства или цели переезда недостаточно для вывода.</p></details><details><summary>Указ 702 гарантирует РВП?</summary><p>Нет. Он даёт право обратиться при соблюдении условий; решение принимается с учётом оснований для отказа.</p></details><p>При противоречиях в документах, прежнем отказе или близком окончании разрешённого пребывания обсудите маршрут <a href="/ru/consultations/">с юристом</a> до подачи.</p>''',
  'fr': '''<p class="sr-meta">Mis à jour le 21 novembre 2026 · Informations générales</p><p>Visa, permis de séjour temporaire (RVP) et titre de séjour (VNZh) ne répondent pas à la même question. Le choix dépend de votre nationalité, du but et de la durée du séjour, de votre famille et des documents déjà obtenus.</p><h2>Comparer les options</h2><table><caption>Carte de préparation, à confronter aux règles en vigueur</caption><thead><tr><th>Voie</th><th>À vérifier</th><th>Erreur fréquente</th></tr></thead><tbody><tr><td>Visa</td><td>Motif, nationalité, poste consulaire, durée</td><td>Confondre visa et droit de résidence durable</td></tr><tr><td>RVP</td><td>Fondement, quota ou exception, région, dossier</td><td>Préparer les pièces sans fondement vérifié</td></tr><tr><td>VNZh</td><td>Voie applicable, statut antérieur, justificatifs</td><td>Copier le parcours d’une autre personne</td></tr></tbody></table><h2>Préparer l’analyse</h2><ol><li>Notez nationalité, résidence et précédents séjours en Russie.</li><li>Décrivez votre projet, votre famille et les échéances.</li><li>Rassemblez passeports, visas et décisions administratives.</li><li>Vérifiez les fondements dans la <a href="http://pravo.gov.ru/proxy/ips/?docbody=&nd=102078147">loi fédérale n° 115-FZ</a>. Pour le programme « valeurs traditionnelles », lisez le <a href="https://publication.pravo.gov.ru/document/0001202408190001">décret n° 702</a> et <a href="/fr/migration/decree-702/">notre analyse</a>.</li><li>Confirmez ensuite les pièces et la procédure de chaque personne.</li></ol><h2>Exemple</h2><p>Dans une famille dont les membres ont des nationalités et des statuts différents, une seule liste de pièces ne suffit pas. Préparez d’abord une fiche par personne, puis une chronologie familiale.</p><h2>Questions fréquentes</h2><details><summary>Peut-on demander directement un VNZh ?</summary><p>Certaines voies particulières existent. Une analyse des faits et de la version actuelle de la loi est nécessaire.</p></details><details><summary>Le décret 702 garantit-il un RVP ?</summary><p>Non. Il ouvre un droit de déposer une demande sous conditions, sans garantir la décision.</p></details><p>Pour un refus antérieur ou des documents contradictoires, <a href="/fr/consultations/">demandez une analyse individuelle</a> avant le dépôt.</p>''',
 },
 'renting-a-home': {
  'ru': '''<p class="sr-meta">Обновлено 21.11.2026 · Информация общего характера</p><p>Перед оплатой квартиры отделите три вопроса: <strong>кто вправе заключить договор, что написано в договоре и как будет решён вопрос миграционного учёта</strong>. Даже хорошая квартира не компенсирует непрозрачные документы.</p><h2>Проверка до оплаты</h2><table><caption>Практический чеклист для арендатора</caption><thead><tr><th>Вопрос</th><th>Что запросить</th><th>Что записать в договоре</th></tr></thead><tbody><tr><td>Стороны</td><td>Личность подписанта, основание распоряжения жильём, полномочия представителя</td><td>Кто сдаёт жильё и кто отвечает за передачу</td></tr><tr><td>Деньги</td><td>Размер и назначение каждого платежа</td><td>Сроки, способ оплаты, возврат обеспечительного платежа</td></tr><tr><td>Жильё</td><td>Адрес, состояние, оборудование, показания счётчиков</td><td>Акт приёма-передачи и порядок устранения недостатков</td></tr><tr><td>Проживание иностранца</td><td>Готовность сторон предоставить документы и участвовать в нужных действиях</td><td>Порядок взаимодействия, без обещания результата госуслуги</td></tr></tbody></table><h2>Пять шагов арендатора</h2><ol><li>Сверьте адрес объявления, осмотра и проекта договора.</li><li>Попросите объяснить полномочия каждого подписанта. При посреднике выясните, кому и за что платите.</li><li>Запишите все платежи и условия возврата до перевода денег.</li><li>Подготовьте фото состояния квартиры и акт передачи без чужих личных данных в публичных материалах.</li><li>Отдельно проверьте применимую процедуру миграционного учёта по <a href="http://kremlin.ru/acts/bank/24033">закону № 109-ФЗ</a>; не считайте договор доказательством постановки на учёт.</li></ol><h2>Пример</h2><p>Объявление размещает агент, договор предлагает подписать родственник собственника, а деньги просят перевести третьему лицу. Пауза до оплаты разумна: запросите документы о полномочиях, объяснение получателя платежа и исправленный договор.</p><h2>Частые вопросы</h2><details><summary>Достаточно ли подписанного договора для миграционного учёта?</summary><p>Нет оснований считать подписание договора подтверждением завершённого учёта. Порядок, заявитель и документы проверяются отдельно.</p></details><details><summary>Можно ли оставить обеспечительный платёж без расписки?</summary><p>Сохраните проверяемое подтверждение передачи денег и согласованные условия возврата. Спорные платежи лучше уточнить до подписания.</p></details><p>Если собственник, адрес или полномочия вызывают сомнения, используйте <a href="/ru/real-estate/legal-check/">юридическую проверку</a> до оплаты.</p>''',
  'fr': '''<p class="sr-meta">Mis à jour le 21 novembre 2026 · Informations générales</p><p>Avant de payer un logement, vérifiez qui signe, ce que prévoit le bail et comment les démarches liées au séjour seront organisées. Traitez ces questions séparément.</p><h2>Liste de contrôle</h2><table><caption>Points à clarifier avant le versement</caption><thead><tr><th>Point</th><th>Vérification</th></tr></thead><tbody><tr><td>Signataire</td><td>Identité, droit de disposer du logement et mandat éventuel</td></tr><tr><td>Paiements</td><td>Loyer, dépôt, frais, justificatifs et remboursement</td></tr><tr><td>Logement</td><td>Adresse, état, équipement et état des lieux</td></tr><tr><td>Séjour</td><td>Documents et coopération nécessaires pour la procédure applicable</td></tr></tbody></table><h2>Procéder étape par étape</h2><ol><li>Comparez l’adresse de l’annonce, de la visite et du contrat.</li><li>Vérifiez l’identité et les pouvoirs des signataires.</li><li>Faites préciser tous les paiements et leur remboursement.</li><li>Consignez l’état du logement à la remise des clés.</li><li>Vérifiez séparément les règles d’enregistrement migratoire selon la <a href="http://kremlin.ru/acts/bank/24033">loi fédérale n° 109-FZ</a>. Un bail signé ne prouve pas que l’enregistrement est achevé.</li></ol><h2>Exemple</h2><p>Une annonce vient d’un intermédiaire, un proche du propriétaire souhaite signer et un tiers veut recevoir l’argent. Demandez une explication écrite des pouvoirs et des paiements avant tout virement.</p><h2>Questions fréquentes</h2><details><summary>Le bail suffit-il pour l’enregistrement migratoire ?</summary><p>Non. La procédure, le demandeur et les pièces doivent être vérifiés séparément.</p></details><details><summary>Peut-on verser le dépôt sans justificatif ?</summary><p>Conservez une preuve vérifiable du versement et des conditions de remboursement. Clarifiez tout montant litigieux avant de signer.</p></details><p>En cas de doute sur les pouvoirs ou le logement, demandez une <a href="/fr/real-estate/legal-check/">vérification juridique</a> avant de payer.</p>''',
 },
 'starting-a-business': {
  'ru': '''<p class="sr-meta">Обновлено 21.11.2026 · Информация общего характера</p><p>Начинайте не с формы заявления, а с модели работы: <strong>что вы продаёте, кому, кто будет участником и руководителем, как поступят деньги</strong>. Регистрация компании или ИП — лишь один из этапов. Миграционный статус, налоги и разрешения на отдельные виды деятельности требуют отдельной оценки.</p><h2>Карта решения</h2><table><caption>Вопросы до выбора формы бизнеса</caption><thead><tr><th>Тема</th><th>Факты для проверки</th><th>Документ или результат</th></tr></thead><tbody><tr><td>Участники</td><td>Гражданство, статус, доли, полномочия</td><td>Схема владения и управления</td></tr><tr><td>Деятельность</td><td>Клиенты, регион, товар/услуга, специальные требования</td><td>Описание модели и необходимые разрешения</td></tr><tr><td>Финансы</td><td>Источники средств, расчёты, налоговые вопросы</td><td>Финансовый план и вопросы налоговому специалисту</td></tr><tr><td>Регистрация</td><td>Компания или ИП, адрес, документы, канал подачи</td><td>Проверенный комплект и последовательность</td></tr></tbody></table><h2>Порядок подготовки</h2><ol><li>Опишите деятельность одним абзацем и перечислите стороны будущих договоров.</li><li>Составьте схему участников и руководства, отметьте иностранное участие.</li><li>Проверьте возможные ограничения и налоговые последствия с профильным специалистом.</li><li>Сравните доступные формы. <a href="https://www.nalog.gov.ru/rn77/ip/interest/reg_ip/petition/">ФНС отдельно описывает регистрацию ИП иностранца</a>, включая документы о личности и праве проживания; инструкция не заменяет индивидуальную проверку.</li><li>Используйте <a href="https://www.nalog.gov.ru/rn77/news/activities_fts/12512122/">сервис ФНС для подготовки регистрации бизнеса</a> после выбора модели.</li></ol><h2>Пример</h2><p>Два партнёра планируют оказывать услуги из России, один из них иностранный гражданин. До регистрации обсудите роль каждого, полномочия директора, адрес, расчёты с клиентами и статус иностранного участника. Одна регистрационная форма не решит эти вопросы.</p><h2>Частые вопросы</h2><details><summary>Может ли иностранец зарегистрировать ИП?</summary><p>ФНС описывает такой порядок, но указывает на документ о праве временного или постоянного проживания. Применимость и полный комплект проверяются для конкретного лица.</p></details><details><summary>Регистрация компании решает вопрос проживания?</summary><p>Нет. Корпоративные и миграционные основания следует анализировать отдельно.</p></details><p>Начать можно с <a href="/ru/business/company-registration/">раздела об открытии компании</a> или <a href="/ru/consultations/">консультации</a>.</p>''',
  'fr': '''<p class="sr-meta">Mis à jour le 21 novembre 2026 · Informations générales</p><p>Avant de choisir une société ou une entreprise individuelle, décrivez l’activité, les clients, les associés, la direction et les flux financiers. L’immigration, la fiscalité et les autorisations éventuelles demandent une analyse distincte.</p><h2>Questions à résoudre</h2><table><caption>Préparer la décision avant l’immatriculation</caption><thead><tr><th>Sujet</th><th>À documenter</th></tr></thead><tbody><tr><td>Associés</td><td>Nationalité, statut, parts et pouvoirs</td></tr><tr><td>Activité</td><td>Clients, région, produits et contraintes particulières</td></tr><tr><td>Finances</td><td>Financement, paiements et fiscalité à examiner</td></tr><tr><td>Formalités</td><td>Structure, adresse, pièces et méthode de dépôt</td></tr></tbody></table><h2>Étapes utiles</h2><ol><li>Décrivez l’activité et les futurs contrats.</li><li>Identifiez les associés et les pouvoirs de gestion.</li><li>Faites examiner les limites et conséquences fiscales.</li><li>Comparez les formes. L’<a href="https://www.nalog.gov.ru/rn77/ip/interest/reg_ip/petition/">administration fiscale russe décrit les pièces pour l’entrepreneur individuel étranger</a>, notamment le document de séjour ; cette notice ne remplace pas l’examen individuel.</li><li>Consultez le <a href="https://www.nalog.gov.ru/rn77/news/activities_fts/12512122/">service d’immatriculation de l’administration fiscale</a> après avoir choisi la structure.</li></ol><h2>Exemple</h2><p>Deux associés, dont un ressortissant étranger, envisagent une activité en Russie. Avant l’immatriculation, clarifiez la direction, l’adresse, les paiements et le statut migratoire de chacun.</p><h2>Questions fréquentes</h2><details><summary>Créer une société donne-t-il un droit de résidence ?</summary><p>Non. L’immatriculation et le fondement du séjour doivent être analysés séparément.</p></details><details><summary>Un étranger peut-il s’immatriculer comme entrepreneur individuel ?</summary><p>L’<a href="https://www.nalog.gov.ru/rn77/ip/interest/reg_ip/petition/">administration fiscale russe</a> prévoit cette démarche avec une pièce établissant le droit de résider temporairement ou durablement en Russie. Vérifiez votre situation et le dossier complet avant de déposer.</p></details><p>Voir <a href="/fr/business/company-registration/">la création d’entreprise</a> ou <a href="/fr/consultations/">demander une consultation</a>.</p>''',
 },
 'investor-checklist': {
  'ru': '''<p class="sr-meta">Обновлено 21.11.2026 · Информация общего характера</p><p>Проверка проекта начинается с ответа на четыре вопроса: <strong>с кем вы заключаете договор, каким активом владеет эта сторона, какие обязательства уже существуют и как вы выйдете из проекта</strong>. Красивой презентации для этого недостаточно.</p><h2>Минимальная карта проверки</h2><table><caption>Объём проверки зависит от сделки и отрасли</caption><thead><tr><th>Блок</th><th>Что запросить</th><th>Риск</th></tr></thead><tbody><tr><td>Контрагент</td><td>Полное наименование, регистрационные данные, полномочия подписанта</td><td>Договор с неподходящей стороной</td></tr><tr><td>Актив</td><td>Основание владения, обременения, ограничения использования</td><td>Невозможность реализовать план</td></tr><tr><td>Обязательства</td><td>Кредиты, судебные споры, гарантии, ключевые договоры</td><td>Неожиданные расходы</td></tr><tr><td>Экономика и выход</td><td>Модель доходов, платежи, условия выхода и разрешения спора</td><td>Невозможность вернуть вложение на ожидаемых условиях</td></tr></tbody></table><h2>Рабочая последовательность</h2><ol><li>Запишите цель вложения и критерии отказа от сделки.</li><li>Проверьте юридическое лицо в <a href="https://www.nalog.gov.ru/rn77/related_activities/registries/">официальных реестрах ФНС</a>; сверьте данные с документами продавца или партнёра.</li><li>Запросите документы об активе и ограничениях. Для недвижимости отдельно проверьте сведения ЕГРН через официальный канал.</li><li>Сопоставьте презентацию, финансовую модель, проект договора и фактические документы; все расхождения запишите.</li><li>До перевода средств согласуйте условия входа, контроля, отчётности, выхода и разрешения спора.</li></ol><h2>Пример</h2><p>Вам предлагают долю в проекте недвижимости, но объект принадлежит другой компании группы. Требуется установить цепочку прав и договоров: покупка доли в одной компании не делает её собственником объекта.</p><h2>Частые вопросы</h2><details><summary>Достаточно ли выписки из ЕГРЮЛ?</summary><p>Нет. Она подтверждает лишь часть регистрационных сведений. Активы, обязательства, полномочия и условия сделки проверяются отдельно.</p></details><details><summary>Проверка гарантирует доходность?</summary><p>Нет. Юридическая проверка выявляет правовые риски, но не гарантирует коммерческий результат.</p></details><p>Обсудите объём <a href="/ru/investments/legal-due-diligence/">юридической проверки проекта</a> до подписания обязательств.</p>''',
  'fr': '''<p class="sr-meta">Mis à jour le 21 novembre 2026 · Informations générales</p><p>Une vérification juridique répond d’abord à quatre questions : qui signe, qui détient l’actif, quelles obligations existent déjà et comment sortir du projet. Une présentation commerciale ne répond pas à ces questions.</p><h2>Carte de contrôle</h2><table><caption>À adapter au type de transaction</caption><thead><tr><th>Sujet</th><th>Pièces et questions</th></tr></thead><tbody><tr><td>Partenaire</td><td>Identité, immatriculation, pouvoirs du signataire</td></tr><tr><td>Actif</td><td>Titre, charges, restrictions d’usage</td></tr><tr><td>Obligations</td><td>Dettes, litiges, contrats importants</td></tr><tr><td>Sortie</td><td>Conditions de paiement, contrôle et retrait</td></tr></tbody></table><h2>Procédure pratique</h2><ol><li>Définissez vos objectifs et les risques inacceptables.</li><li>Vérifiez la société dans les <a href="https://www.nalog.gov.ru/rn77/related_activities/registries/">registres officiels de l’administration fiscale</a>.</li><li>Demandez les titres et les justificatifs relatifs à l’actif ; pour un immeuble, vérifiez les données du registre immobilier officiel.</li><li>Comparez présentation, modèle financier, documents et contrat.</li><li>Convenez des clauses de contrôle, de sortie et de règlement des différends avant tout paiement.</li></ol><h2>Exemple</h2><p>Une participation est proposée dans une société, mais l’immeuble annoncé appartient à une autre entité. Il faut vérifier la chaîne de propriété et les contrats.</p><h2>Questions fréquentes</h2><details><summary>Un extrait du registre des sociétés suffit-il ?</summary><p>Non. Il ne montre qu’une partie des informations nécessaires.</p></details><details><summary>L’audit garantit-il le rendement ?</summary><p>Non. Il examine les risques juridiques, sans garantir un résultat économique.</p></details><p>Définissez le périmètre d’une <a href="/fr/investments/legal-due-diligence/">vérification juridique</a> avant de signer.</p>''',
 },
}
